func TestNewMachineIDIsValidAndUnique(t *testing.T) {
	seen := map[string]bool{}
	for range 1000 {
		id := NewMachineID()
		if !entityid.Valid(id) || seen[id] {
			t.Fatalf("machine ID %q is malformed or repeated", id)
		}
		seen[id] = true
	}
}

