func (a App) Validate() error {
	if !tokenRE.MatchString(a.Name) || !entityid.Valid(a.ID) || a.Version == 0 {
		return fmt.Errorf("%w: app name, ID or version", ErrInvalid)
	}
	switch {
	case a.Class == ClassPlatform && a.Tenant == "":
	case a.Class == ClassTenant && entityid.Valid(a.Tenant):
	default:
		return fmt.Errorf("%w: app %s class %q needs a tenant exactly when it is a tenant app", ErrInvalid, a.Name, a.Class)
	}
	if len(a.Regions) > maxListed {
		return fmt.Errorf("%w: app %s has too many regions", ErrInvalid, a.Name)
	}
	for region, count := range a.Regions {
		if !validRegion(region) || count < 0 || count > MaxMachines {
			return fmt.Errorf("%w: app %s region %q count %d", ErrInvalid, a.Name, region, count)
		}
	}
	if a.NodePool != "" && !poolRE.MatchString(a.NodePool) {
		return fmt.Errorf("%w: app %s node pool", ErrInvalid, a.Name)
	}
	if err := a.Config.Validate(); err != nil {
		return fmt.Errorf("app %s: %w", a.Name, err)
	}
	if err := a.AppSpec.Validate(a.Name); err != nil {
		return fmt.Errorf("%w: app %s: %w", ErrInvalid, a.Name, err)
	}
	if a.Stateful != nil {
		for region, count := range a.Regions {
			if count != 0 && count-a.Update.Unavailable() < a.Stateful.Quorum {
				return fmt.Errorf("%w: app %s region %s: %d machines less %d updating at once are below quorum %d",
					ErrInvalid, a.Name, region, count, a.Update.Unavailable(), a.Stateful.Quorum)
			}
		}
	}
	// The platform app named after its role gets the role's signed profile,
	// Vault secrets included. The app is not signed, so every program it
	// starts, by command, hook or exec check, must be inside its admitted
	// tarball: no host or image program, such as /bin/sh, runs beside those
	// secrets.
	if a.Class == ClassPlatform && a.Name == a.Config.Role {
		argvs := [][]string{a.Config.Command, a.Config.Lifecycle.PostStart, a.Config.Lifecycle.PreStop}
		for _, check := range a.Config.Checks {
			argvs = append(argvs, check.Command)
		}
		for _, argv := range argvs {
			if len(argv) != 0 && !a.Config.InArtifact(argv) {
				return fmt.Errorf("%w: app %s gets its role's secrets, so it starts only programs inside its tarball, not %q",
					ErrInvalid, a.Name, argv[0])
			}
		}
	}
	return nil
}

func (c MachineConfig) Validate() error {
	if !tokenRE.MatchString(c.Role) || !digestRE.MatchString(c.Digest) {
		return fmt.Errorf("%w: config role or digest", ErrInvalid)
	}
	if c.Resources.CPU <= 0 || c.Resources.MemoryBytes <= 0 || c.Resources.DiskBytes <= 0 {
		return fmt.Errorf("%w: config resources must be positive", ErrInvalid)
	}
	if len(c.Args) > maxListed || len(c.Env) > maxListed {
		return fmt.Errorf("%w: too many arguments or environment variables", ErrInvalid)
	}
	for _, arg := range c.Args {
		if len(arg) > maxArgBytes {
			return fmt.Errorf("%w: argument too long", ErrInvalid)
		}
	}
	for key, value := range c.Env {
		if !envRE.MatchString(key) || len(value) > maxArgBytes {
			return fmt.Errorf("%w: environment variable %q", ErrInvalid, key)
		}
	}
	if len(c.Services) > maxListed || len(c.Checks) > maxListed {
		return fmt.Errorf("%w: too many services or checks", ErrInvalid)
	}
	var names []string
	var ports []int
	for _, service := range c.Services {
		if !tokenRE.MatchString(service.Name) || !validPort(service.Port) ||
			slices.Contains(names, service.Name) || slices.Contains(ports, service.Port) {
			return fmt.Errorf("%w: service %q", ErrInvalid, service.Name)
		}
		names, ports = append(names, service.Name), append(ports, service.Port)
	}
	names = nil
	for _, check := range c.Checks {
		if err := check.validate(); err != nil || slices.Contains(names, check.Name) {
			return fmt.Errorf("%w: check %q", ErrInvalid, check.Name)
		}
		names = append(names, check.Name)
	}
	switch c.Restart.Policy {
	case "", RestartAlways, RestartNo:
		if c.Restart.MaxRetries != 0 {
			return fmt.Errorf("%w: max retries need the on-failure policy", ErrInvalid)
		}
	case RestartOnFailure:
		if c.Restart.MaxRetries < 1 || c.Restart.MaxRetries > 100 {
			return fmt.Errorf("%w: max retries must be within 1..100", ErrInvalid)
		}
	default:
		return fmt.Errorf("%w: restart policy %q", ErrInvalid, c.Restart.Policy)
	}
	if err := c.MachineSpec.Validate(); err != nil {
		return fmt.Errorf("%w: %w", ErrInvalid, err)
	}
	return nil
}

func (c Check) validate() error {
	if !tokenRE.MatchString(c.Name) ||
		c.IntervalSeconds < 0 || c.IntervalSeconds > 3600 || c.TimeoutSeconds < 0 || c.TimeoutSeconds > 300 ||
		c.GraceSeconds < 0 || c.GraceSeconds > 3600 {
		return ErrInvalid
	}
	switch c.Type {
	case CheckHTTP:
		if validPort(c.Port) && strings.HasPrefix(c.Path, "/") && len(c.Path) <= maxArgBytes && len(c.Command) == 0 {
			return nil
		}
	case CheckTCP:
		if validPort(c.Port) && c.Path == "" && len(c.Command) == 0 {
			return nil
		}
	case CheckExec:
		if c.Port == 0 && c.Path == "" && len(c.Command) > 0 && len(c.Command) <= maxListed &&
			!slices.ContainsFunc(c.Command, func(arg string) bool { return len(arg) > maxArgBytes }) {
			return nil
		}
	}
	return ErrInvalid
}

func (m Machine) Validate() error {
	if !entityid.Valid(m.ID) || !tokenRE.MatchString(m.App) || !entityid.Valid(m.AppID) ||
		!validRegion(m.Region) || m.Version == 0 {
		return fmt.Errorf("%w: machine identity or version", ErrInvalid)
	}
	if m.Host != "" && !tokenRE.MatchString(m.Host) || m.FailureDomain != "" && (m.Host == "" || !tokenRE.MatchString(m.FailureDomain)) {
		return fmt.Errorf("%w: machine %s host or failure domain", ErrInvalid, m.ID)
	}
	switch m.Desired {
	case DesiredStarted, DesiredStopped, DesiredDestroyed:
	default:
		return fmt.Errorf("%w: machine %s desired state %q", ErrInvalid, m.ID, m.Desired)
	}
	if err := m.Config.Validate(); err != nil {
		return fmt.Errorf("machine %s: %w", m.ID, err)
	}
	return nil
}

func (s Status) Validate() error {
	if !entityid.Valid(s.ID) || !tokenRE.MatchString(s.App) || !slices.Contains(states, s.State) || s.UpdatedAt.IsZero() {
		return fmt.Errorf("%w: machine status", ErrInvalid)
	}
	return nil
}

func validRegion(region string) bool {
	_, ok := catalog.LookupName(region)
	return ok
}

func Plan(in ScheduleInput) Schedule {
	plan := Schedule{Pending: map[string]int{}, Held: map[string]error{}}
	s := newScheduler(in)
	// Statuses by their machine's key.
	statuses := make(map[string]Status, len(in.Statuses))
	for _, status := range in.Statuses {
		statuses[machineKey(status.App, status.ID)] = status
	}
	apps := make(map[string]App, len(in.Apps))
	for _, app := range in.Apps {
		apps[app.Name] = app
	}
	byApp := map[string][]Machine{}
	for _, machine := range sortedMachines(in.Machines) {
		status := statuses[machine.key()]
		// A record goes once it is stored as destroyed and its process is
		// known to be gone: never placed, or observed destroyed.
		if machine.Desired == DesiredDestroyed && (machine.Host == "" || status.State == StateDestroyed) {
			plan.Delete = append(plan.Delete, machine)
			continue
		}
		host, registered := s.hosts[machine.Host]
		next := machine
		if app, exists := apps[machine.App]; !exists || app.ID != machine.AppID {
			next.Desired = DesiredDestroyed
		}
		switch {
		case machine.Host != "" && !registered:
			// The host is gone for good, and its machines with it.
			next.Desired = DesiredDestroyed
			if status.State != StateDestroyed {
				plan.Statuses = append(plan.Statuses, withState(status, machine, StateDestroyed))
			}
		case machine.Host != "" && host.Lost:
			// A partitioned host may come back: its machine is replaced and
			// stopped on return, never assumed stopped.
			next.Desired = DesiredDestroyed
			if status.State != StateLost && status.State != StateDestroyed {
				plan.Statuses = append(plan.Statuses, withState(status, machine, StateLost))
			}
		}
		if next.Desired != machine.Desired {
			plan.Update = append(plan.Update, next)
		}
		// A destroyed machine holds its host until it is observed gone.
		s.charge(next, 1)
		if next.Desired != DesiredDestroyed {
			byApp[next.App] = append(byApp[next.App], next)
		}
	}

	for _, name := range slices.Sorted(maps.Keys(apps)) {
		app := apps[name]
		if slices.Contains(in.Reserved, app.Config.Role) {
			plan.Held[name] = fmt.Errorf("role %s is still placed by the cell spec or TerraBase placement", app.Config.Role)
			continue
		}
		live := byApp[name]
		want := app.Regions[in.Region]
		// Scale in: unplaced machines first, then failed ones, then those
		// in the most crowded failure domain, then by ID. A destroyed record
		// is deleted on a later pass.
		slices.SortStableFunc(live, func(a, b Machine) int {
			return cmp.Or(
				cmp.Compare(boolRank(a.Host != ""), boolRank(b.Host != "")),
				cmp.Compare(boolRank(statuses[a.key()].State != StateFailed), boolRank(statuses[b.key()].State != StateFailed)),
				-cmp.Compare(s.domains[name][a.FailureDomain], s.domains[name][b.FailureDomain]),
				cmp.Compare(a.ID, b.ID))
		})
		for len(live) > want {
			victim := live[0]
			live = live[1:]
			s.charge(victim, -1)
			victim.Desired = DesiredDestroyed
			plan.Update = appendMachine(plan.Update, victim)
		}
		for _, machine := range live {
			next := machine
			if next.Version < app.Version {
				s.charge(next, -1)
				next.Version, next.Config = app.Version, app.Config
				if next.Host != "" && !s.room(app, next.Config, s.hosts[next.Host]) {
					// ponytail: a host that no longer fits the new version
					// keeps the old one; replace such machines with a surge
					// when resizing becomes common.
					next = machine
				}
				s.charge(next, 1)
			}
			if next.Host == "" {
				if host, ok := s.choose(app, next.Config); ok {
					next.Host, next.FailureDomain = host.Node, host.FailureDomain
					s.charge(next, 1)
				} else {
					plan.Pending[name]++
				}
			}
			if !sameJSON(next, machine) {
				plan.Update = appendMachine(plan.Update, next)
			}
		}
		for range want - len(live) {
			machine := Machine{ID: NewMachineID(), App: name, AppID: app.ID, Region: in.Region,
				Version: app.Version, Config: app.Config, Desired: DesiredStarted}
			if host, ok := s.choose(app, machine.Config); ok {
				machine.Host, machine.FailureDomain = host.Node, host.FailureDomain
				s.charge(machine, 1)
			} else {
				plan.Pending[name]++
			}
			plan.Create = append(plan.Create, machine)
		}
	}
	return plan
}

func newScheduler(in ScheduleInput) *scheduler {
	s := &scheduler{hosts: map[string]Host{}, used: map[string]placement.Resources{},
		ports: map[string]map[int]int{}, apps: map[string]map[string]int{}, domains: map[string]map[string]int{}}
	for _, host := range in.Hosts {
		s.hosts[host.Node] = host
		s.ports[host.Node], s.apps[host.Node] = map[int]int{}, map[string]int{}
	}
	return s
}

func (s *scheduler) charge(machine Machine, sign int) {
	if machine.Host == "" {
		return
	}
	if _, ok := s.hosts[machine.Host]; !ok {
		return
	}
	used := s.used[machine.Host]
	used.CPU += sign * machine.Config.Resources.CPU
	used.MemoryBytes += int64(sign) * machine.Config.Resources.MemoryBytes
	used.DiskBytes += int64(sign) * machine.Config.Resources.DiskBytes
	s.used[machine.Host] = used
	for _, service := range machine.Config.Services {
		s.ports[machine.Host][service.Port] += sign
	}
	s.apps[machine.Host][machine.App] += sign
	if s.domains[machine.App] == nil {
		s.domains[machine.App] = map[string]int{}
	}
	s.domains[machine.App][machine.FailureDomain] += sign
}

func (s *scheduler) fits(app App, config MachineConfig, host Host) bool {
	return host.CurrentSession && host.Admitted && host.Healthy && !host.Cordoned && !host.Lost &&
		(app.NodePool == "" || host.Pool == app.NodePool) && s.room(app, config, host)
}

func (s *scheduler) room(app App, config MachineConfig, host Host) bool {
	if !slices.Contains(host.Roles, config.Role) || s.apps[host.Node][app.Name] > 0 {
		return false
	}
	free := s.free(host)
	if free.CPU < config.Resources.CPU || free.MemoryBytes < config.Resources.MemoryBytes ||
		free.DiskBytes < config.Resources.DiskBytes {
		return false
	}
	for _, service := range config.Services {
		if s.ports[host.Node][service.Port] > 0 {
			return false
		}
	}
	return true
}

func (s *scheduler) free(host Host) placement.Resources {
	used := s.used[host.Node]
	return placement.Resources{
		CPU:         host.Capacity.CPU - host.Allocated.CPU - used.CPU,
		MemoryBytes: host.Capacity.MemoryBytes - host.Allocated.MemoryBytes - used.MemoryBytes,
		DiskBytes:   host.Capacity.DiskBytes - host.Allocated.DiskBytes - used.DiskBytes,
	}
}

func (s *scheduler) choose(app App, config MachineConfig) (Host, bool) {
	var best Host
	var bestDomain int
	var bestRoom float64
	found := false
	for _, node := range slices.Sorted(maps.Keys(s.hosts)) {
		host := s.hosts[node]
		if !s.fits(app, config, host) {
			continue
		}
		domain := s.domains[app.Name][host.FailureDomain]
		free := s.free(host)
		room := max(
			float64(free.CPU-config.Resources.CPU)/float64(host.Capacity.CPU),
			float64(free.MemoryBytes-config.Resources.MemoryBytes)/float64(host.Capacity.MemoryBytes))
		if !found || domain < bestDomain || domain == bestDomain && room < bestRoom {
			best, bestDomain, bestRoom, found = host, domain, room, true
		}
	}
	return best, found
}

func sortedMachines(machines []Machine) []Machine {
	sorted := slices.Clone(machines)
	slices.SortFunc(sorted, func(a, b Machine) int { return cmp.Or(cmp.Compare(a.App, b.App), cmp.Compare(a.ID, b.ID)) })
	return sorted
}

func appendMachine(writes []Machine, machine Machine) []Machine {
	if index := slices.IndexFunc(writes, func(m Machine) bool { return m.key() == machine.key() }); index >= 0 {
		writes[index] = machine
		return writes
	}
	return append(writes, machine)
}

func withState(status Status, machine Machine, state State) Status {
	if status.Revision == 0 {
		status = Status{ID: machine.ID, App: machine.App}
	}
	status.State = state
	return status
}

func boolRank(value bool) int {
	if value {
		return 1
	}
	return 0
}

func OpenStore(ctx context.Context, js jetstream.JetStream, region string, replicas int, fencer authority.Fencer) (*Store, error) {
	if js == nil || fencer == nil || !validRegion(region) || replicas != 1 && replicas != 3 && replicas != 5 {
		return nil, fmt.Errorf("%w: store configuration", ErrInvalid)
	}
	open := func(bucket, description string) (jetstream.KeyValue, error) {
		kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
			Bucket: bucket, Description: description, History: 4, MaxValueSize: maxRecordBytes,
			MaxBytes: BucketMaxBytes, Storage: jetstream.FileStorage, Replicas: replicas,
		})
		if err != nil {
			return nil, fmt.Errorf("open %s: %w", bucket, err)
		}
		return kv, nil
	}
	apps, err := open(Bucket, "ts-orch apps and machines")
	if err != nil {
		return nil, err
	}
	machines, err := open(MachineBucket, "ts-orch machines")
	if err != nil {
		return nil, err
	}
	statuses, err := open(StatusBucket, "ts-orch observed machine states")
	if err != nil {
		return nil, err
	}
	if _, err := list[App](ctx, apps, ">"); err != nil {
		return nil, fmt.Errorf("app inventory requires current-format state: %w", err)
	}
	inventory, err := list[Machine](ctx, machines, "*")
	if err != nil {
		return nil, err
	}
	for _, machine := range inventory {
		entry, err := machines.Get(ctx, machine.App+"."+machine.ID)
		if err != nil {
			return nil, fmt.Errorf("machine %s has no readable app index: %w", machine.ID, err)
		}
		if string(entry.Value()) != machine.ID {
			return nil, fmt.Errorf("%w: machine %s app index", ErrInvalid, machine.ID)
		}
	}
	return &Store{apps: apps, machines: machines, statuses: statuses, region: region, fencer: fencer}, nil
}

func (s *Store) App(ctx context.Context, name string) (App, error) {
	return get[App](ctx, s.apps, appKey(name))
}

func (s *Store) Apps(ctx context.Context) ([]App, error) {
	apps, err := list[App](ctx, s.apps, "*")
	slices.SortFunc(apps, func(a, b App) int { return cmp.Compare(a.Name, b.Name) })
	return apps, err
}

func (s *Store) PutApp(ctx context.Context, epoch uint64, app App) (App, error) {
	if app.Revision == 0 {
		app.ID, app.Version = newID(), 1
	} else {
		current, err := s.App(ctx, app.Name)
		if err != nil {
			return App{}, err
		}
		if current.Revision != app.Revision {
			return App{}, fmt.Errorf("%w: %s", ErrConflict, app.key())
		}
		if app.ID != current.ID || app.Class != current.Class || app.Tenant != current.Tenant {
			return App{}, fmt.Errorf("%w: app %s ID, class and tenant never change", ErrInvalid, app.Name)
		}
		app.Version = current.Version
		if !sameJSON(app.Config, current.Config) {
			app.Version++
		} else if sameJSON(app, current) {
			return current, nil
		}
	}
	if err := app.Validate(); err != nil {
		return App{}, err
	}
	if err := put(ctx, s, s.apps, epoch, &app); err != nil {
		return App{}, err
	}
	return app, nil
}

func (s *Store) DeleteApp(ctx context.Context, epoch uint64, app App) error {
	machines, err := s.Machines(ctx, app.Name)
	if err != nil {
		return err
	}
	if len(machines) != 0 {
		return fmt.Errorf("%w: %s has %d", ErrHasMachines, app.Name, len(machines))
	}
	return remove(ctx, s, s.apps, epoch, app.key(), app.Revision)
}

func (s *Store) Machine(ctx context.Context, app, id string) (Machine, error) {
	if !entityid.Valid(id) {
		return Machine{}, ErrInvalid
	}
	value, err := get[Machine](ctx, s.machines, machineKey(app, id))
	if err == nil && value.App != app {
		return Machine{}, ErrNotFound
	}
	return value, err
}

func (s *Store) Machines(ctx context.Context, app string) ([]Machine, error) {
	var machines []Machine
	var err error
	if app == "" {
		machines, err = list[Machine](ctx, s.machines, "*")
	} else {
		var ids []string
		ids, err = s.appMachineIDs(ctx, app)
		for _, id := range ids {
			machine, readErr := s.Machine(ctx, app, id)
			if errors.Is(readErr, ErrNotFound) {
				continue
			}
			if readErr != nil {
				return nil, readErr
			}
			machines = append(machines, machine)
		}
	}
	slices.SortFunc(machines, func(a, b Machine) int { return cmp.Or(cmp.Compare(a.App, b.App), cmp.Compare(a.ID, b.ID)) })
	return machines, err
}

func (s *Store) PutMachine(ctx context.Context, epoch uint64, machine Machine) (Machine, error) {
	if err := machine.Validate(); err != nil {
		return Machine{}, err
	}
	if machine.Revision == 0 {
		if _, err := s.machines.Get(ctx, machine.ID); err == nil {
			return Machine{}, fmt.Errorf("%w: %s", ErrConflict, machine.ID)
		} else if !errors.Is(err, jetstream.ErrKeyNotFound) {
			return Machine{}, err
		}
		if machine.Region != s.region {
			return Machine{}, fmt.Errorf("%w: machine %s is not in region %s", ErrInvalid, machine.ID, s.region)
		}
		app, err := s.App(ctx, machine.App)
		if err != nil {
			return Machine{}, err
		}
		if app.ID != machine.AppID {
			return Machine{}, fmt.Errorf("%w: machine %s names another incarnation of app %s", ErrInvalid, machine.ID, app.Name)
		}
	} else {
		current, err := s.Machine(ctx, machine.App, machine.ID)
		if err != nil {
			return Machine{}, err
		}
		if current.Revision != machine.Revision {
			return Machine{}, fmt.Errorf("%w: %s", ErrConflict, machine.key())
		}
		switch {
		case machine.AppID != current.AppID || machine.Region != current.Region:
			return Machine{}, fmt.Errorf("%w: machine %s app and region never change", ErrInvalid, machine.ID)
		case current.Host != "" && (machine.Host != current.Host || machine.FailureDomain != current.FailureDomain):
			return Machine{}, fmt.Errorf("%w: machine %s host never changes once placed", ErrInvalid, machine.ID)
		case current.Desired == DesiredDestroyed && machine.Desired != DesiredDestroyed:
			return Machine{}, fmt.Errorf("%w: machine %s is destroyed", ErrInvalid, machine.ID)
		}
	}
	// Publish the index first: a crash may leave an empty lookup, never an invisible machine.
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return Machine{}, err
	}
	if _, err := s.machines.Put(ctx, machine.App+"."+machine.ID, []byte(machine.ID)); err != nil {
		return Machine{}, err
	}
	if err := put(ctx, s, s.machines, epoch, &machine); err != nil {
		return Machine{}, err
	}
	return machine, nil
}

func (s *Store) Status(ctx context.Context, app, id string) (Status, error) {
	if !entityid.Valid(id) {
		return Status{}, ErrInvalid
	}
	value, err := get[Status](ctx, s.statuses, statusKey(app, id))
	if err == nil && value.App != app {
		return Status{}, ErrNotFound
	}
	return value, err
}

func (s *Store) Statuses(ctx context.Context, app string) ([]Status, error) {
	var statuses []Status
	var err error
	if app == "" {
		statuses, err = list[Status](ctx, s.statuses, "*")
	} else {
		var ids []string
		ids, err = s.appMachineIDs(ctx, app)
		for _, id := range ids {
			status, readErr := s.Status(ctx, app, id)
			if errors.Is(readErr, ErrNotFound) {
				continue
			}
			if readErr != nil {
				return nil, readErr
			}
			statuses = append(statuses, status)
		}
	}
	slices.SortFunc(statuses, func(a, b Status) int { return cmp.Or(cmp.Compare(a.App, b.App), cmp.Compare(a.ID, b.ID)) })
	return statuses, err
}

func (s *Store) PutStatus(ctx context.Context, epoch uint64, status Status) (Status, error) {
	status.UpdatedAt = time.Now().UTC()
	if err := status.Validate(); err != nil {
		return Status{}, err
	}
	if _, err := s.Machine(ctx, status.App, status.ID); err != nil {
		return Status{}, err
	}
	if status.Revision != 0 {
		current, err := s.Status(ctx, status.App, status.ID)
		if err != nil {
			return Status{}, err
		}
		if current.Revision != status.Revision {
			return Status{}, fmt.Errorf("%w: %s", ErrConflict, status.key())
		}
		if current.State == StateDestroyed && status.State != StateDestroyed {
			return Status{}, fmt.Errorf("%w: machine %s is destroyed", ErrInvalid, status.ID)
		}
	}
	if err := put(ctx, s, s.statuses, epoch, &status); err != nil {
		return Status{}, err
	}
	return status, nil
}

func (s *Store) appMachineIDs(ctx context.Context, app string) ([]string, error) {
	if !tokenRE.MatchString(app) {
		return nil, fmt.Errorf("%w: app name", ErrInvalid)
	}
	watcher, err := s.machines.WatchFiltered(ctx, []string{app + ".*"}, jetstream.IgnoreDeletes())
	if err != nil {
		return nil, err
	}
	defer stopWatch(watcher)
	var ids []string
	seen := make(map[string]bool)
	var bad error
	for {
		select {
		case entry, ok := <-watcher.Updates():
			if !ok {
				return nil, fmt.Errorf("app machine index watcher closed early")
			}
			if entry == nil {
				if bad != nil {
					return nil, bad
				}
				return ids, nil
			}
			id := strings.TrimPrefix(entry.Key(), app+".")
			if !entityid.Valid(id) || string(entry.Value()) != id {
				bad = fmt.Errorf("%w: app machine index entry", ErrInvalid)
			} else if !seen[id] {
				seen[id] = true
				ids = append(ids, id)
			}
		case <-ctx.Done():
			return nil, ctx.Err()
		}
	}
}

func decode[T any, P record[T]](key string, data []byte, revision uint64) (T, error) {
	var value T
	if err := protocol.DecodeStrict(data, &value, maxRecordBytes); err != nil {
		return value, fmt.Errorf("%w: %s: %v", ErrInvalid, key, err)
	}
	if err := P(&value).Validate(); err != nil {
		return value, fmt.Errorf("%s: %w", key, err)
	}
	if P(&value).key() != key {
		return value, fmt.Errorf("%w: %s holds the record of %s", ErrInvalid, key, P(&value).key())
	}
	*P(&value).revision() = revision
	return value, nil
}

func get[T any, P record[T]](ctx context.Context, kv jetstream.KeyValue, key string) (T, error) {
	entry, err := kv.Get(ctx, key)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return *new(T), fmt.Errorf("%w: %s", ErrNotFound, key)
	}
	if err != nil {
		return *new(T), fmt.Errorf("read %s: %w", key, err)
	}
	return decode[T, P](key, entry.Value(), entry.Revision())
}

func list[T any, P record[T]](ctx context.Context, kv jetstream.KeyValue, filter string) ([]T, error) {
	watcher, err := kv.WatchFiltered(ctx, []string{filter}, jetstream.IgnoreDeletes())
	if err != nil {
		return nil, fmt.Errorf("list %s: %w", filter, err)
	}
	defer stopWatch(watcher)
	var values []T
	var bad error
	for {
		select {
		case entry, ok := <-watcher.Updates():
			if !ok {
				return nil, fmt.Errorf("list %s: watcher closed early", filter)
			}
			if entry == nil {
				if bad != nil {
					return nil, bad
				}
				return values, nil
			}
			// Keep reading after a bad record: the watcher blocks on unread
			// values.
			if value, err := decode[T, P](entry.Key(), entry.Value(), entry.Revision()); err != nil {
				bad = errors.Join(bad, err)
			} else {
				values = append(values, value)
			}
		case <-ctx.Done():
			return nil, fmt.Errorf("list %s: %w", filter, ctx.Err())
		}
	}
}

func stopWatch(watcher jetstream.KeyWatcher) {
	_ = watcher.Stop()
	go func() {
		timeout := time.NewTimer(time.Minute)
		defer timeout.Stop()
		for {
			select {
			case _, ok := <-watcher.Updates():
				if !ok {
					return
				}
			case <-timeout.C:
				return
			}
		}
	}()
}

func sameJSON(a, b any) bool {
	left, leftErr := protocol.EncodeJSON(a)
	right, rightErr := protocol.EncodeJSON(b)
	return leftErr == nil && rightErr == nil && string(left) == string(right)
}

func put[T any, P record[T]](ctx context.Context, s *Store, kv jetstream.KeyValue, epoch uint64, value P) error {
	key := value.key()
	data, err := protocol.EncodeJSON(value)
	if err != nil {
		return err
	}
	if len(data) > maxRecordBytes {
		return fmt.Errorf("%w: %s exceeds %d bytes", ErrInvalid, key, maxRecordBytes)
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	revision := value.revision()
	var written uint64
	if *revision == 0 {
		written, err = kv.Create(ctx, key, data)
	} else {
		written, err = kv.Update(ctx, key, data, *revision)
	}
	if errors.Is(err, jetstream.ErrKeyExists) || errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
		return fmt.Errorf("%w: %s", ErrConflict, key)
	}
	if err != nil {
		return fmt.Errorf("write %s: %w", key, err)
	}
	*revision = written
	return nil
}

func remove(ctx context.Context, s *Store, kv jetstream.KeyValue, epoch uint64, key string, revision uint64) error {
	if revision == 0 {
		return fmt.Errorf("%w: delete %s needs its revision", ErrInvalid, key)
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	err := kv.Delete(ctx, key, jetstream.LastRevision(revision))
	if errors.Is(err, jetstream.ErrKeyRevisionMismatch) || errors.Is(err, jetstream.ErrKeyExists) {
		return fmt.Errorf("%w: %s", ErrConflict, key)
	}
	if err != nil {
		return fmt.Errorf("delete %s: %w", key, err)
	}
	return nil
}

func NewAt(at time.Time) string {
	mu.Lock()
	defer mu.Unlock()
	return ulid.MustNew(ulid.Timestamp(at), entropy).String()
}

func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

func Derive(domain string, values ...string) string {
	h := sha256.New()
	for _, value := range append([]string{domain}, values...) {
		var size [8]byte
		binary.BigEndian.PutUint64(size[:], uint64(len(value)))
		h.Write(size[:])
		h.Write([]byte(value))
	}
	return ulid.MustNew(0, bytes.NewReader(h.Sum(nil)[:10])).String()
}

func LookupName(name string) (Entry, bool) {
	for _, entry := range entries {
		if entry.Name() == name {
			return entry, true
		}
	}
	return Entry{}, false
}

func (m MachineSpec) Validate() error {
	switch m.Artifact {
	case "", ArtifactBinary:
		if m.Image != "" || len(m.Command) != 0 {
			return fmt.Errorf("%w: a binary takes no image or command", ErrInvalid)
		}
	case ArtifactTarball:
		if m.Image != "" || len(m.Command) == 0 || !relativePath(m.Command[0]) {
			return fmt.Errorf("%w: a tarball needs a command whose first entry is a path inside it, and no image", ErrInvalid)
		}
	case ArtifactImage:
		if !validImage(m.Image) {
			return fmt.Errorf("%w: image %q must be a registry's repository without a tag or digest", ErrInvalid, m.Image)
		}
	default:
		return fmt.Errorf("%w: artifact %q", ErrInvalid, m.Artifact)
	}
	for _, argv := range [][]string{m.Command, m.Lifecycle.PostStart, m.Lifecycle.PreStop} {
		if len(argv) > maxListed || slices.ContainsFunc(argv, func(arg string) bool {
			return len(arg) > maxArgBytes || strings.ContainsRune(arg, 0)
		}) || len(argv) != 0 && !m.entrypoint(argv[0]) {
			return fmt.Errorf("%w: command or hook %q", ErrInvalid, argv)
		}
	}
	if m.Lifecycle.DrainSeconds < 0 || m.Lifecycle.DrainSeconds > maxDrainSeconds {
		return fmt.Errorf("%w: drain must be within 0..%d seconds", ErrInvalid, maxDrainSeconds)
	}
	if len(m.Files) > maxListed {
		return fmt.Errorf("%w: too many files", ErrInvalid)
	}
	// No path may hold another or a system path.
	paths := slices.Clone(systemPaths)
	for _, file := range m.Files {
		if !placedPath(file.Path) || slices.ContainsFunc(paths, nests(file.Path)) {
			return fmt.Errorf("%w: file path %q", ErrInvalid, file.Path)
		}
		paths = append(paths, file.Path)
	}
	// Marshal also refuses text that is not UTF-8.
	encoded, err := json.Marshal(m)
	if err != nil {
		return fmt.Errorf("%w: %v", ErrInvalid, err)
	}
	if len(encoded) > maxEncodedBytes {
		return fmt.Errorf("%w: spec exceeds %d bytes", ErrInvalid, maxEncodedBytes)
	}
	return nil
}

func validImage(image string) bool {
	match := imageRE.FindStringSubmatch(image)
	if len(image) > maxImageBytes || match == nil {
		return false
	}
	port, err := strconv.Atoi(match[1])
	return match[1] == "" || err == nil && port >= 1 && port <= 65535
}

func (m MachineSpec) InArtifact(argv []string) bool {
	return m.Artifact == ArtifactTarball && len(argv) != 0 && relativePath(argv[0])
}

func (m MachineSpec) entrypoint(name string) bool {
	switch {
	case path.IsAbs(name):
		return placedPath(name)
	case m.Artifact == ArtifactTarball:
		return relativePath(name)
	case m.Artifact == ArtifactImage:
		return pathRE.MatchString(name) && !strings.Contains(name, "/") && name != "." && name != ".."
	}
	return false
}

func relativePath(p string) bool {
	return len(p) <= maxArgBytes && pathRE.MatchString(p) && !path.IsAbs(p) && path.Clean(p) == p &&
		p != "." && p != ".." && !strings.HasPrefix(p, "../")
}

func placedPath(p string) bool {
	return len(p) <= maxArgBytes && pathRE.MatchString(p) && path.IsAbs(p) && path.Clean(p) == p
}

func nests(p string) func(string) bool {
	return func(other string) bool {
		return other == p || strings.HasPrefix(p, other+"/") || strings.HasPrefix(other, p+"/")
	}
}

func (a AppSpec) Strategy() Strategy {
	switch {
	case a.Update.Strategy != "":
		return a.Update.Strategy
	case a.Stateful != nil:
		return Rolling
	default:
		return AllAtOnce
	}
}

func (a AppSpec) Validate(app string) error {
	if a.Placement.MaxPerFailureDomain < 0 || a.Placement.MaxPerFailureDomain > maxMachines {
		return fmt.Errorf("%w: max per failure domain", ErrInvalid)
	}
	switch a.Update.Strategy {
	case "", AllAtOnce, Rolling:
	default:
		return fmt.Errorf("%w: update strategy %q", ErrInvalid, a.Update.Strategy)
	}
	if a.Update.MaxUnavailable < 0 || a.Update.MaxUnavailable > maxMachines ||
		a.Update.MaxUnavailable != 0 && a.Strategy() != Rolling {
		return fmt.Errorf("%w: max unavailable needs a rolling update within 0..%d", ErrInvalid, maxMachines)
	}
	if a.Stateful != nil {
		if a.Stateful.Quorum < 0 || a.Stateful.Quorum > maxMachines {
			return fmt.Errorf("%w: quorum must be within 0..%d", ErrInvalid, maxMachines)
		}
		// Updating every member together would drop the quorum.
		if a.Strategy() != Rolling {
			return fmt.Errorf("%w: a stateful app updates rolling", ErrInvalid)
		}
	}
	if len(a.DependsOn) > maxListed {
		return fmt.Errorf("%w: too many dependencies", ErrInvalid)
	}
	for index, dependency := range a.DependsOn {
		if !tokenRE.MatchString(dependency) || dependency == app || slices.Contains(a.DependsOn[:index], dependency) {
			return fmt.Errorf("%w: dependency %q", ErrInvalid, dependency)
		}
	}
	return nil
}

func EncodeJSON(value any) ([]byte, error) {
	encoded, err := json.Marshal(value, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode protocol JSON: %w", err)
	}
	return encoded, nil
}

func DecodeStrict(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, true)
}

func decode(data []byte, destination any, maxBytes int, rejectUnknown bool) error {
	if maxBytes == 0 {
		maxBytes = DefaultMaxJSONBytes
	}
	if maxBytes < 0 {
		return fmt.Errorf("%w: negative byte limit", ErrInvalidJSON)
	}
	if len(data) > maxBytes {
		return ErrJSONTooLarge
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%w: invalid UTF-8", ErrInvalidJSON)
	}
	if err := json.Unmarshal(data, destination,
		json.RejectUnknownMembers(rejectUnknown),
		jsontext.AllowDuplicateNames(false),
	); err != nil {
		return fmt.Errorf("decode protocol JSON: %w", err)
	}
	return nil
}
